const roleRank: Record<MembershipRole, number> = { VIEWER: 0, REVIEWER: 1, ANALYST: 2, ADMIN: 3, OWNER: 4 };
const jsonClone = <T>(value: T): T => JSON.parse(JSON.stringify(value)) as T;

function evidence(input: Omit<AIResponseEvidenceInput, "statementId" | "confidence"> & { statementId?: string; confidence?: AIResponseEvidenceInput["confidence"] }): AIResponseEvidenceInput {
  return { statementId: input.statementId ?? input.evidenceRef.replace(/[^A-Za-z0-9]+/g, "-").slice(0, 80), confidence: input.confidence ?? "HIGH", ...input };
}

function makeTool(input: Omit<AIToolDefinition, "validate"> & { schema?: { parse(value: unknown): unknown } }): AIToolDefinition {
  return { ...input, validate: (arguments_) => (input.schema ?? emptyArgumentsSchema).parse(arguments_) as Record<string, unknown> };
}

function scenarioOf(context: RelevantContextPackage, args: Record<string, unknown>): ScenarioKey {
  return (args.scenario as ScenarioKey | undefined) ?? context.selection.financialScenario;
}

function engineEvidence(context: RelevantContextPackage, scenario: ScenarioKey, field: string, value?: string): AIResponseEvidenceInput {
  return evidence({ sourceType: "ENGINE", entityType: "StudyVersion", entityId: context.workspace.bundle.studyVersionId, field, version: `v${context.workspace.bundle.studyVersionNumber}`, scenario, evidenceRef: `engine:${context.workspace.bundle.studyVersionId}:${scenario}:${field}`, label: `Engine · v${context.workspace.bundle.studyVersionNumber} · ${scenario}`, value });
}

const aiDesignConfidence = (value: DesignConfidence): AIResponseEvidenceInput["confidence"] => value === "NOT_VERIFIED" ? "NOT_AVAILABLE" : value;

function applySimulationChanges(base: ProjectAssumptions, raw: Record<string, number>): ProjectAssumptions {
  const next = { ...base };
  if (raw.unitPricePercent !== undefined) next.unitPrice = new Decimal(base.unitPrice).mul(new Decimal(1).plus(new Decimal(raw.unitPricePercent).div(100))).toFixed(2);
  if (raw.constructionCostPercent !== undefined) next.constructionCostPerM2 = new Decimal(base.constructionCostPerM2).mul(new Decimal(1).plus(new Decimal(raw.constructionCostPercent).div(100))).toFixed(2);
  if (raw.landPriceDelta !== undefined) next.landPrice = Decimal.max(0, new Decimal(base.landPrice).plus(raw.landPriceDelta)).toFixed(2);
  if (raw.approvalMonthsDelta !== undefined) next.approvalMonths = Math.max(0, base.approvalMonths + raw.approvalMonthsDelta);
  if (raw.salesVelocityPercent !== undefined) next.salesVelocityUnitsMonth = Decimal.max(0.01, new Decimal(base.salesVelocityUnitsMonth).mul(new Decimal(1).plus(new Decimal(raw.salesVelocityPercent).div(100)))).toFixed(4);
  if (raw.financingRateDeltaPp !== undefined) next.annualFinancingRate = Decimal.max(0, new Decimal(base.annualFinancingRate).plus(raw.financingRateDeltaPp)).toFixed(4);
  if (raw.units !== undefined) next.units = raw.units;
  return next;
}

async function changeContext(context: RelevantContextPackage, args: Record<string, unknown>): Promise<AIToolCallResult> {
  const requested = contextChangeSchema.parse(args);
  const selection = { ...context.selection };
  if (requested.financialScenario) selection.financialScenario = requested.financialScenario;
  if (requested.latestVersion) {
    const latest = await prisma.investmentSnapshotBundle.findFirst({ where: { investmentCaseId: context.workspace.id, investmentCase: { organizationId: context.organizationId } }, orderBy: { version: "desc" }, select: { id: true, content: true } });
    if (!latest) throw new Error("O Investment Case ainda não possui snapshot disponível.");
    const content = latest.content as unknown as typeof context.workspace.bundle;
    selection.studyVersionId = content.studyVersionId;
    selection.studyVersionNumber = content.studyVersionNumber;
    selection.snapshotBundleId = latest.id;
    selection.financialScenario = content.scenario;
    const selectedUrban = content.land?.scenarios.find((item) => item.id === content.land?.selectedScenarioId);
    selection.urbanScenarioId = selectedUrban?.id ?? null;
    selection.urbanScenarioType = selectedUrban?.type ?? null;
  }
  if (requested.studyVersionNumber && requested.studyVersionNumber !== selection.studyVersionNumber) {
    const rows = await prisma.investmentSnapshotBundle.findMany({ where: { investmentCaseId: context.workspace.id, investmentCase: { organizationId: context.organizationId } }, select: { id: true, content: true } });
    const bundle = rows.find((row) => (row.content as { studyVersionNumber?: number }).studyVersionNumber === requested.studyVersionNumber);
    if (!bundle) throw new Error(`A versão v${requested.studyVersionNumber} não possui snapshot neste Investment Case.`);
    const content = bundle.content as unknown as typeof context.workspace.bundle;
    selection.studyVersionId = content.studyVersionId;
    selection.studyVersionNumber = content.studyVersionNumber;
    selection.snapshotBundleId = bundle.id;
  }
  if (requested.urbanScenarioType) {
    const urban = context.workspace.bundle.land?.scenarios.find((item) => item.type === requested.urbanScenarioType);
    if (!urban) throw new Error(`O cenário urbanístico ${requested.urbanScenarioType} não está disponível no snapshot atual.`);
    selection.urbanScenarioId = urban.id;
    selection.urbanScenarioType = urban.type;
  }
  await persistContextSelection(context.organizationId, context.conversationId, selection);
  return { name: "changeContext", mode: "READ_ONLY", status: "COMPLETED", data: selection };
}

export class AIToolRegistry {
  private readonly tools = new Map<string, AIToolDefinition>();
  constructor() { for (const tool of createTools()) this.tools.set(tool.name, tool); }
  list() { return [...this.tools.values()].map(({ name, description, mode, minimumRole }) => ({ name, description, mode, minimumRole })); }
  get(name: string) { return this.tools.get(name); }
  async execute(context: RelevantContextPackage, name: string, rawArguments: Record<string, unknown>): Promise<AIToolCallResult> {
    const tool = this.tools.get(name);
    if (!tool) throw new Error(`Ferramenta não autorizada: ${name}`);
    if (roleRank[context.role] < roleRank[tool.minimumRole]) throw new Error("Seu perfil não possui permissão para esta ferramenta.");
    if (tool.mode === "SIMULATION" && !context.permissions.canSimulate) throw new Error("Seu perfil não pode executar simulações.");
    if (tool.mode === "MUTATION" && !context.permissions.canMutate) throw new Error("Seu perfil não pode executar esta ação.");
    const arguments_ = tool.validate(rawArguments);
    return tool.execute(context, arguments_);
  }
}

